      "content": "import {\n\tVELA_CLI_FAILURE_ENVELOPE_FIELDS,\n\ttype CommentBatchPushRequest,\n\ttype CommentBatchPushResponse,\n} from \"@open-design/contracts\";\nimport {\n\tparseCommentBatchReceipt,\n\tvalidateCommentBatchRequest,\n} from \"./comment-batch-receipt.js\";\nimport type {\n\tCollabCloudComment,\n\tCollabCloudMemberDirectoryEntry,\n\tCollabMemberRole,\n\tCollabPresenceMember,\n} from \"@open-design/contracts\";\nimport {\n\tassertMemberPageQuery,\n\tCollabCloudError,\n\tmemberPageRebuildResult,\n\tparseMemberPage,\n\ttype CollabCloudMemberPageQuery,\n\ttype CollabCloudMemberPageResult,\n} from \"../integrations/collab-cloud.js\";\nimport {\n\trunVelaCommand,\n\tvelaCommandStdout,\n\ttype VelaCommandOptions,\n\tvelaWorkspaceCommandOptions,\n} from \"../integrations/vela-command.js\";\n\nexport type RunVelaCollab = (\n\targs: string[],\n\tworkspaceId?: string,\n\toptions?: Pick<VelaCommandOptions, \"input\">,\n) => Promise<string>;\n\nexport interface VelaCliCollabClientOptions {\n\trun?: RunVelaCollab;\n}\n\ntype MemberWire = {\n\tmemberId?: unknown;\n\tdisplayName?: unknown;\n\trole?: unknown;\n\tavatarUrl?: unknown;\n};\n\ntype PresenceWire = MemberWire & {\n\tfilePath?: unknown;\n\tactivity?: unknown;\n\theartbeatAt?: unknown;\n};\n\ntype PullCommentsWire = {\n\tcomments?: unknown;\n\tlatestSeq?: unknown;\n};\n\n/** Retain the service's author snapshot rather than hashing local identity IDs. */\nfunction toCloudComment(value: unknown): CollabCloudComment {\n\tif (!value || typeof value !== \"object\" || Array.isArray(value)) {\n\t\treturn value as CollabCloudComment;\n\t}\n\tconst wire = value as CollabCloudComment & { author?: unknown };\n\tconst author =\n\t\twire.author &&\n\t\ttypeof wire.author === \"object\" &&\n\t\t!Array.isArray(wire.author)\n\t\t\t? (wire.author as { authorKey?: unknown; displayName?: unknown })\n\t\t\t: null;\n\tif (!author) return wire;\n\treturn {\n\t\t...wire,\n\t\t...(typeof author.authorKey === \"string\" && autho